   625  bool OpenTypeSILF::SILSub::
   626  SILPass::ParsePart(Buffer& table, const size_t SILSub_init_offset,
   627                                    const size_t next_pass_offset) {
   628    size_t init_offset = table.offset();
   629    if (!table.ReadU8(&this->flags)) {
   630      return parent->Error("SILPass: Failed to read flags");
   631        // checks omitted
   632    }
   633    if (!table.ReadU8(&this->maxRuleLoop)) {
   634      return parent->Error("SILPass: Failed to read valid maxRuleLoop");
   635    }
   636    if (!table.ReadU8(&this->maxRuleContext)) {
   637      return parent->Error("SILPass: Failed to read maxRuleContext");
   638    }
   639    if (!table.ReadU8(&this->maxBackup)) {
   640      return parent->Error("SILPass: Failed to read maxBackup");
   641    }
   642    if (!table.ReadU16(&this->numRules)) {
   643      return parent->Error("SILPass: Failed to read numRules");
   644    }
   645    if (parent->version >> 16 >= 2) {
   646      if (!table.ReadU16(&this->fsmOffset)) {
   647        return parent->Error("SILPass: Failed to read fsmOffset");
   648      }
   649      if (!table.ReadU32(&this->pcCode) ||
   650          (parent->version >= 3 && this->pcCode < this->fsmOffset)) {
   651        return parent->Error("SILPass: Failed to read pcCode");
   652      }
   653    }
   654    if (!table.ReadU32(&this->rcCode) ||
   655        (parent->version >> 16 >= 2 && this->rcCode < this->pcCode)) {
   656      return parent->Error("SILPass: Failed to read valid rcCode");
   657    }
   658    if (!table.ReadU32(&this->aCode) || this->aCode < this->rcCode) {
   659      return parent->Error("SILPass: Failed to read valid aCode");
   660    }
   661    if (!table.ReadU32(&this->oDebug) ||
   662        (this->oDebug && this->oDebug < this->aCode)) {
   663      return parent->Error("SILPass: Failed to read valid oDebug");
   664    }
   665    if (parent->version >> 16 >= 3 &&
   666        table.offset() != init_offset + this->fsmOffset) {
   667      return parent->Error("SILPass: fsmOffset check failed");
   668    }
   669    if (!table.ReadU16(&this->numRows) ||
   670        (this->oDebug && this->numRows < this->numRules)) {
   671      return parent->Error("SILPass: Failed to read valid numRows");
   672    }
   673    if (!table.ReadU16(&this->numTransitional)) {
   674      return parent->Error("SILPass: Failed to read numTransitional");
   675    }
   676    if (!table.ReadU16(&this->numSuccess)) {
   677      return parent->Error("SILPass: Failed to read numSuccess");
   678    }
   679    if (!table.ReadU16(&this->numColumns)) {
   680      return parent->Error("SILPass: Failed to read numColumns");
   681    }
   682    if (!table.ReadU16(&this->numRange)) {
   683      return parent->Error("SILPass: Failed to read numRange");
   684    }
   685
   686    // The following three fields are deprecated and ignored. We fix them up here
   687    // just for internal consistency, but the Graphite engine doesn't care.
   688    if (!table.ReadU16(&this->searchRange) ||
   689        !table.ReadU16(&this->entrySelector) ||
   690        !table.ReadU16(&this->rangeShift)) {
   691      return parent->Error("SILPass: Failed to read searchRange..rangeShift");
   692    }
   693    if (this->numRange == 0) {
   694      if (this->searchRange != 0 || this->entrySelector != 0 || this->rangeShift != 0) {
   695        this->searchRange = this->entrySelector = this->rangeShift = 0;
   696      }
   697    } else {
   698      unsigned floorLog2 = std::floor(std::log2(this->numRange));
   699      if (this->searchRange != 6 * (unsigned)std::pow(2, floorLog2) ||
   700          this->entrySelector != floorLog2 ||
   701          this->rangeShift != 6 * this->numRange - this->searchRange) {
   702        this->searchRange = 6 * (unsigned)std::pow(2, floorLog2);
   703        this->entrySelector = floorLog2;
   704        this->rangeShift = 6 * this->numRange - this->searchRange;
   705      }
   706    }
   707
   708    //this->ranges.resize(this->numRange, parent);
   709    for (unsigned i = 0 ; i < this->numRange; ++i) {
   710      this->ranges.emplace_back(parent);
   711      if (!this->ranges[i].ParsePart(table)) {
   712        return parent->Error("SILPass: Failed to read ranges[%u]", i);
   713      }
   714    }
   715    unsigned ruleMap_len = 0;  // maximum value in oRuleMap
   716    //this->oRuleMap.resize(static_cast<unsigned long>(this->numSuccess) + 1);
   717    for (unsigned long i = 0; i <= this->numSuccess; ++i) {
   718      this->oRuleMap.emplace_back();
   719      if (!table.ReadU16(&this->oRuleMap[i])) {
   720        return parent->Error("SILPass: Failed to read oRuleMap[%u]", i);
   721      }
   722      if (oRuleMap[i] > ruleMap_len) {
   723        ruleMap_len = oRuleMap[i];
   724      }
   725    }
   726
   727    //this->ruleMap.resize(ruleMap_len);
   728    for (unsigned i = 0; i < ruleMap_len; ++i) {
   729      this->ruleMap.emplace_back();
   730      if (!table.ReadU16(&this->ruleMap[i])) {
   731        return parent->Error("SILPass: Failed to read ruleMap[%u]", i);
   732      }
   733    }
   734
   735    if (!table.ReadU8(&this->minRulePreContext)) {
   736      return parent->Error("SILPass: Failed to read minRulePreContext");
   737    }
   738    if (!table.ReadU8(&this->maxRulePreContext) ||
   739        this->maxRulePreContext < this->minRulePreContext) {
   740      return parent->Error("SILPass: Failed to read valid maxRulePreContext");
   741    }
   742
   743    unsigned startStates_len = this->maxRulePreContext - this->minRulePreContext
   744                               + 1;
   745      // this->minRulePreContext <= this->maxRulePreContext
   746    //this->startStates.resize(startStates_len);
   747    for (unsigned i = 0; i < startStates_len; ++i) {
   748      this->startStates.emplace_back();
   749      if (!table.ReadS16(&this->startStates[i])) {
   750        return parent->Error("SILPass: Failed to read startStates[%u]", i);
   751      }
   752    }
   753
   754    //this->ruleSortKeys.resize(this->numRules);
   755    for (unsigned i = 0; i < this->numRules; ++i) {
   756      this->ruleSortKeys.emplace_back();
   757      if (!table.ReadU16(&this->ruleSortKeys[i])) {
   758        return parent->Error("SILPass: Failed to read ruleSortKeys[%u]", i);
   759      }
   760    }
   761
   762    //this->rulePreContext.resize(this->numRules);
   763    for (unsigned i = 0; i < this->numRules; ++i) {
   764      this->rulePreContext.emplace_back();
   765      if (!table.ReadU8(&this->rulePreContext[i])) {
   766        return parent->Error("SILPass: Failed to read rulePreContext[%u]", i);
   767      }
   768    }
   769
   770    if (parent->version >> 16 >= 2) {
   771      if (!table.ReadU8(&this->collisionThreshold)) {
   772        return parent->Error("SILPass: Failed to read collisionThreshold");
   773      }
   774      if (!table.ReadU16(&this->pConstraint)) {
   775        return parent->Error("SILPass: Failed to read pConstraint");
   776      }
   777    }
   778
   779    unsigned long ruleConstraints_len = this->aCode - this->rcCode;
   780      // this->rcCode <= this->aCode
   781    //this->oConstraints.resize(static_cast<unsigned long>(this->numRules) + 1);
   782    for (unsigned long i = 0; i <= this->numRules; ++i) {
   783      this->oConstraints.emplace_back();
   784      if (!table.ReadU16(&this->oConstraints[i]) ||
   785          this->oConstraints[i] > ruleConstraints_len) {
   786        return parent->Error("SILPass: Failed to read valid oConstraints[%lu]",
   787                             i);
   788      }
   789    }
   790
   791    if (!this->oDebug && this->aCode > next_pass_offset) {
   792      return parent->Error("SILPass: Failed to calculate length of actions");
   793    }
   794    unsigned long actions_len = this->oDebug ? this->oDebug - this->aCode :
   795                                               next_pass_offset - this->aCode;
   796      // if this->oDebug, then this->aCode <= this->oDebug
   797    //this->oActions.resize(static_cast<unsigned long>(this->numRules) + 1);
   798    for (unsigned long i = 0; i <= this->numRules; ++i) {
   799      this->oActions.emplace_back();
   800      if (!table.ReadU16(&this->oActions[i]) ||
   801          (this->oActions[i] > actions_len)) {
   802        return parent->Error("SILPass: Failed to read valid oActions[%lu]", i);
   803      }
   804    }
   805
   806    //this->stateTrans.resize(this->numTransitional);
   807    for (unsigned i = 0; i < this->numTransitional; ++i) {
   808      this->stateTrans.emplace_back();
   809      //this->stateTrans[i].resize(this->numColumns);
   810      for (unsigned j = 0; j < this->numColumns; ++j) {
   811        this->stateTrans[i].emplace_back();
   812        if (!table.ReadU16(&stateTrans[i][j])) {
   813          return parent->Error("SILPass: Failed to read stateTrans[%u][%u]",
   814                               i, j);
   815        }
   816      }
   817    }
   818
   819    if (parent->version >> 16 >= 2) {
   820      if (!table.ReadU8(&this->reserved2)) {
   821        return parent->Error("SILPass: Failed to read reserved2");
   822      }
   823      if (this->reserved2 != 0) {
   824        parent->Warning("SILPass: Nonzero reserved2");
   825      }
   826
   827      if (table.offset() != SILSub_init_offset + this->pcCode) {
   828        return parent->Error("SILPass: pcCode check failed");
   829      }
   830      //this->passConstraints.resize(this->pConstraint);
   831      for (unsigned i = 0; i < this->pConstraint; ++i) {
   832        this->passConstraints.emplace_back();
   833        if (!table.ReadU8(&this->passConstraints[i])) {
   834          return parent->Error("SILPass: Failed to read passConstraints[%u]", i);
   835        }
   836      }
   837    }
   838
   839    if (table.offset() != SILSub_init_offset + this->rcCode) {
   840      return parent->Error("SILPass: rcCode check failed");
   841    }
   842    //this->ruleConstraints.resize(ruleConstraints_len);  // calculated above
   843    for (unsigned long i = 0; i < ruleConstraints_len; ++i) {
   844      this->ruleConstraints.emplace_back();
   845      if (!table.ReadU8(&this->ruleConstraints[i])) {
   846        return parent->Error("SILPass: Failed to read ruleConstraints[%u]", i);
   847      }
   848    }
   849
   850    if (table.offset() != SILSub_init_offset + this->aCode) {
   851      return parent->Error("SILPass: aCode check failed");
   852    }
   853    //this->actions.resize(actions_len);  // calculated above
   854    for (unsigned long i = 0; i < actions_len; ++i) {
   855      this->actions.emplace_back();
   856      if (!table.ReadU8(&this->actions[i])) {
   857        return parent->Error("SILPass: Failed to read actions[%u]", i);
   858      }
   859    }
   860
   861    if (this->oDebug) {
   862      OpenTypeNAME* name = static_cast<OpenTypeNAME*>(
   863          parent->GetFont()->GetTypedTable(OTS_TAG_NAME));
   864      if (!name) {
   865        return parent->Error("SILPass: Required name table is missing");
   866      }
   867
   868      if (table.offset() != SILSub_init_offset + this->oDebug) {
   869        return parent->Error("SILPass: oDebug check failed");
   870      }
   871      //this->dActions.resize(this->numRules);
   872      for (unsigned i = 0; i < this->numRules; ++i) {
   873        this->dActions.emplace_back();
   874        if (!table.ReadU16(&this->dActions[i]) ||
   875            !name->IsValidNameId(this->dActions[i])) {
   876          return parent->Error("SILPass: Failed to read valid dActions[%u]", i);
   877        }
   878      }
   879
   880      unsigned dStates_len = this->numRows - this->numRules;
   881        // this->numRules <= this->numRows
   882      //this->dStates.resize(dStates_len);
   883      for (unsigned i = 0; i < dStates_len; ++i) {
   884        this->dStates.emplace_back();
   885        if (!table.ReadU16(&this->dStates[i]) ||
   886            !name->IsValidNameId(this->dStates[i])) {
   887          return parent->Error("SILPass: Failed to read valid dStates[%u]", i);
   888        }
   889      }
   890
   891      //this->dCols.resize(this->numRules);
   892      for (unsigned i = 0; i < this->numRules; ++i) {
   893        this->dCols.emplace_back();
   894        if (!table.ReadU16(&this->dCols[i]) ||
   895            !name->IsValidNameId(this->dCols[i])) {
   896          return parent->Error("SILPass: Failed to read valid dCols[%u]");
   897        }
   898      }
   899    }
   900    return true;
   901  }
